(() => {
  const PROPERTIES = ["padding","borderTopWidth","backgroundColor","color","fontSize","fontFamily"];
  const HOOKS = ["h2","section.panel-demo[data-surface][data-state]","p.state","p.line"];
  const read = (el) => {
    if (!el) return null;
    const cs = getComputedStyle(el);
    const values = {};
    for (const p of PROPERTIES) values[p] = cs[p];
    return { tag: el.tagName.toLowerCase(), values };
  };
  const baselineSheet = () =>
    [...document.styleSheets].find((s) => (s.href || '').endsWith('/panel/styles.css')) || null;
  const sheets = () => {
    const out = [];
    for (const sheet of document.styleSheets) {
      let rules = null;
      let error = null;
      try { rules = sheet.cssRules ? sheet.cssRules.length : null; } catch (e) { error = String((e && e.message) || e); }
      out.push({
        href: sheet.href,
        ownerTag: sheet.ownerNode ? sheet.ownerNode.tagName : null,
        media: sheet.media ? sheet.media.mediaText : null,
        disabled: sheet.disabled === true,
        rules,
        error,
      });
    }
    return out;
  };
  // Declared values from the sheet's own rules through the CSSOM. A style rule carries an empty
  // cssRules list of its own in current Chrome (nesting), so a nested rule is one that HAS rules.
  const declared = (el) => {
    const sheet = baselineSheet();
    if (!sheet || !el) return null;
    const out = [];
    const walk = (rules, condition) => {
      for (const rule of rules) {
        if (rule.cssRules && rule.cssRules.length > 0) {
          const next = rule.media ? rule.media.mediaText : (rule.conditionText || condition);
          walk(rule.cssRules, next === undefined ? condition : next);
          continue;
        }
        const selectorText = rule.selectorText;
        if (!selectorText) continue;
        let matches = false;
        try { matches = el.matches(selectorText); } catch { matches = false; }
        if (!matches) continue;
        const own = {};
        for (const p of PROPERTIES) {
          const v = rule.style.getPropertyValue(p.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase()));
          if (v !== '') own[p] = v;
        }
        out.push({
          selectorText,
          media: condition === undefined ? null : condition,
          applies: condition === undefined || condition === null ? true : window.matchMedia(condition).matches,
          properties: own,
        });
      }
    };
    walk(sheet.cssRules, null);
    return out;
  };
  const measure = () => {
    const hooks = {};
    for (const hook of HOOKS) {
      const el = document.querySelector(hook);
      hooks[hook] = { found: !!el, computed: read(el), declared: declared(el) };
    }
    const link = document.querySelector('link[rel="stylesheet"]');
    const bare = document.createElement('div');
    bare.setAttribute('data-m054-probe', 'injected-default');
    document.body.appendChild(bare);
    const injected = {
      html: read(document.documentElement),
      body: read(document.body),
      unnamedDiv: read(bare),
    };
    bare.remove();
    const section = document.querySelector('section.panel-demo[data-surface][data-state]');
    return {
      documentUrl: location.href,
      documentClass: location.protocol + '//',
      scheme: window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light',
      devicePixelRatio: window.devicePixelRatio,
      visualViewportScale: window.visualViewport ? window.visualViewport.scale : null,
      styleSheets: sheets(),
      baselineHref: baselineSheet() ? baselineSheet().href : null,
      baselineMedia: baselineSheet() ? baselineSheet().media.mediaText : null,
      baselineDisabled: baselineSheet() ? baselineSheet().disabled === true : null,
      baselineRules: baselineSheet() ? baselineSheet().cssRules.length : null,
      linkElement: link ? link.outerHTML : null,
      surface: section
        ? {
            dataSurface: section.getAttribute('data-surface'),
            dataState: section.getAttribute('data-state'),
            heading: ((section.querySelector('h2') || {}).textContent || '').trim(),
            stateLine: ((section.querySelector('p.state') || {}).textContent || '').trim(),
            lines: [...section.querySelectorAll('p.line')].map((p) => p.textContent.trim()).slice(0, 3),
          }
        : null,
      properties: PROPERTIES,
      hooks,
      injected,
    };
  };

  return measure();
})()

